  function renderSidebar(){const n=state.days.length;$('#day-count').textContent=n+' дн.';$('#day-list').innerHTML=state.days.map((d,i)=>'<button class="day-link'+(activeId===d.id?' active':'')+'" data-id="'+d.id+'" draggable="true"><span class="step">'+String(i+1).padStart(2,'0')+'</span><span class="day-link-text"><strong>'+esc(d.title||'Новый день')+'</strong><small>День '+(i+1)+'</small></span><span class="grip">⠿</span></button>').join('');}
