  let needsBoardLayout=false;
  function structuredLayout(){return state.days.every((d,i)=>i%3===0||Math.abs(d.y-state.days[i-i%3].y)<2&&Math.abs(d.x-state.days[i-1].x-cardWidth(state.days[i-1])-60)<2);}
  function layoutDays(){if(mobile()||mode==='travel')needsBoardLayout=true;let y=20;for(let i=0;i<state.days.length;i+=3){const group=state.days.slice(i,i+3);let x=30;group.forEach(d=>{d.x=x;d.y=y;const el=$('[data-id="'+d.id+'"]',cards);if(el){el.style.left=x+'px';el.style.top=y+'px';}x+=cardWidth(d)+60;});y+=Math.max(...group.map(d=>$('[data-id="'+d.id+'"]',cards)?.offsetHeight||650))+80;}draw();}
